var angular_default = "---\nlayout: article\ntitle: Start with Angular\ndescription: Learn how to use Appwrite to add authentication, user management, file storage, and more to your Angular apps.\ndifficulty: beginner\nreadtime: 3\nback: /docs/quick-starts\n---\n\n\nLearn how to setup your first Angular project powered by Appwrite.\n{% section #step-1 step=1 title=\"Create project\" %}\nHead to the [Appwrite Console](https://cloud.appwrite.io/console).\n\n{% only_dark %}\n![Create project screen](/images/docs/quick-starts/dark/create-project.avif)\n{% /only_dark %}\n{% only_light %}\n![Create project screen](/images/docs/quick-starts/create-project.avif)\n{% /only_light %}\n\nIf this is your first time using Appwrite, create an account and create your first project.\n\nThen, under **Add a platform**, add a **Web app**. The **Hostname** should be `localhost`.\n\n{% partial file=\"note-on-cors.md\" /%}\n\n{% only_dark %}\n![Add a platform](/images/docs/quick-starts/dark/add-platform.avif)\n{% /only_dark %}\n{% only_light %}\n![Add a platform](/images/docs/quick-starts/add-platform.avif)\n{% /only_light %}\n\nYou can skip optional steps.\n\n{% /section %}\n{% section #step-2 step=2 title=\"Create Angular project\" %}\nCreate an Angular project.\n\nIf you don't have Angular CLI installed, run this command.\n```sh\nnpm install -g @angular/cli\n```\n\nThen, create a project.\n\n```sh\nng new my-app\ncd my-app\n```\n\n{% /section %}\n{% section #step-3 step=3 title=\"Install Appwrite\" %}\n\nInstall the JavaScript Appwrite SDK.\n\n```sh\nnpm install appwrite\n```\n{% /section %}\n{% section #step-4 step=4 title=\"Import Appwrite\" %}\nFind your project's ID in the **Settings** page.\n\n{% only_dark %}\n![Project settings screen](/images/docs/quick-starts/dark/project-id.avif)\n{% /only_dark %}\n{% only_light %}\n![Project settings screen](/images/docs/quick-starts/project-id.avif)\n{% /only_light %}\nCreate a new file `src/lib/appwrite.ts` and add the following code to it, replace `<PROJECT_ID>` with your project ID.\n\n```client-web\nimport { Client, Account} from 'appwrite';\n\nexport const client = new Client();\n\nclient\n    .setEndpoint('https://<REGION>.cloud.appwrite.io/v1')\n    .setProject('<PROJECT_ID>'); // Replace with your project ID\n\nexport const account = new Account(client);\nexport { ID } from 'appwrite';\n```\n{% /section %}\n{% section #step-5 step=5 title=\"Create a login page\" %}\nFirst, add imports for the `FormsModule` from Angular to handle the login form..\n\n```ts\nimport { FormsModule } from '@angular/forms';\n...\n@NgModule({\n  declarations: [\n    // ...\n  ],\n  imports: [\n    // ...\n    FormsModule\n  ],\n  providers: [],\n  bootstrap: [AppComponent]\n})\nexport class AppModule { }\n```\n\nThen, replace the contents of `src/app/app.component.html`.\n```html\n<div>\n  <p>\n    {{ loggedInUser ? 'Logged in as ' + loggedInUser.name : 'Not logged in' }}\n  </p>\n\n  <div>\n    <input type=\"email\" placeholder=\"Email\" [(ngModel)]=\"email\" />\n    <input type=\"password\" placeholder=\"Password\" [(ngModel)]=\"password\" />\n    <input type=\"text\" placeholder=\"Name\" [(ngModel)]=\"name\" />\n\n    <button (click)=\"login(email, password)\">\n      Login\n    </button>\n\n    <button (click)=\"register(email, password, name)\">\n      Register\n    </button>\n\n    <button (click)=\"logout()\">\n      Logout\n    </button>\n  </div>\n</div>\n```\n\nLastly, update `src/app/app.component.ts`.\n```ts\nimport { Component } from '@angular/core';\nimport { account, ID } from '../lib/appwrite';\n@Component({\n  selector: 'app-root',\n  templateUrl: './app.component.html',\n  styleUrls: ['./app.component.css']\n})\nexport class AppComponent {\n  loggedInUser: any = null;\n  email: string = '';\n  password: string = '';\n  name: string = '';\n\n  async login(email: string, password: string) {\n    await account.createEmailPasswordSession({\n      email,\n      password\n    });\n    this.loggedInUser = await account.get();\n  }\n\n  async register(email: string, password: string, name: string) {\n    await account.create({\n      userId: ID.unique(),\n      email,\n      password,\n      name\n    });\n    this.login(email, password);\n  }\n\n  async logout() {\n    await account.deleteSession({\n      sessionId: 'current'\n    });\n    this.loggedInUser = null;\n  }\n}\n```\n\n{% /section %}\n\n{% section #step-6 step=6 title=\"All set\" %}\nRun your project with `ng serve --port 3000` and open [Localhost on Port 3000](http://localhost:3000) in your browser.\n{% /section %}";
export { angular_default as default };
